// Process parallel AI responses and extract insights
const response = $input.item.json;

const results = response.results || [];
const successful = results.filter(r => !r.error);
const failed = results.filter(r => r.error);

// Extract recommendations from each provider
const recommendations = successful.map(result => ({
  provider: result.provider,
  model: result.model,
  recommendation: result.response,
  tokens: result.usage.total_tokens,
  confidence: calculateConfidence(result.response)
}));

// Calculate consensus score
const consensusScore = calculateConsensus(recommendations);

// Find common themes
const commonThemes = findCommonThemes(recommendations);

// Determine best recommendation
const bestRecommendation = recommendations.reduce((best, current) => 
  current.confidence > best.confidence ? current : best
, recommendations[0] || {});

return {
  json: {
    request_id: response.request_id,
    prompt: response.prompt,
    timestamp: response.timestamp,

    // Summary
    summary: {
      total_providers: response.summary.total_providers,
      successful: response.summary.successful,
      failed: response.summary.failed,
      total_tokens: response.summary.total_tokens,
      response_time_ms: response.summary.response_time_ms,
      consensus_score: consensusScore
    },

    // All recommendations
    recommendations: recommendations,

    // Analysis
    analysis: {
      common_themes: commonThemes,
      best_recommendation: bestRecommendation,
      agreement_level: consensusScore > 0.7 ? 'high' : consensusScore > 0.4 ? 'moderate' : 'low',
      requires_human_review: consensusScore < 0.4 || failed.length > 0
    },

    // Failed providers (if any)
    failures: failed.map(f => ({
      provider: f.provider,
      error: f.error
    }))
  }
};

// Helper function: Calculate confidence based on response characteristics
function calculateConfidence(text) {
  let score = 0.5; // Base score

  // Specific recommendations score higher
  if (text.match(/\b(recommend|suggest|best|perfect|ideal)\b/i)) score += 0.1;

  // Detailed explanations score higher
  if (text.length > 100) score += 0.1;

  // Numbers and specifics score higher
  if (text.match(/\d+/)) score += 0.1;

  // Business reasoning scores higher
  if (text.match(/\b(cost|profit|revenue|customers|sales)\b/i)) score += 0.1;

  // Cultural authenticity scores higher
  if (text.match(/\b(Romanian|Transylvanian|traditional|authentic)\b/i)) score += 0.1;

  return Math.min(score, 1.0);
}

// Helper function: Calculate consensus between recommendations
function calculateConsensus(recs) {
  if (recs.length < 2) return 1.0;

  let totalSimilarity = 0;
  let comparisons = 0;

  for (let i = 0; i < recs.length; i++) {
    for (let j = i + 1; j < recs.length; j++) {
      totalSimilarity += calculateSimilarity(recs[i].recommendation, recs[j].recommendation);
      comparisons++;
    }
  }

  return comparisons > 0 ? totalSimilarity / comparisons : 0;
}

// Helper function: Calculate text similarity
function calculateSimilarity(text1, text2) {
  const words1 = text1.toLowerCase().match(/\b\w+\b/g) || [];
  const words2 = text2.toLowerCase().match(/\b\w+\b/g) || [];

  const set1 = new Set(words1);
  const set2 = new Set(words2);

  const intersection = new Set([...set1].filter(x => set2.has(x)));
  const union = new Set([...set1, ...set2]);

  return union.size > 0 ? intersection.size / union.size : 0;
}

// Helper function: Find common themes across recommendations
function findCommonThemes(recs) {
  const allText = recs.map(r => r.recommendation).join(' ').toLowerCase();

  const themes = [];

  // Check for common food items
  const foods = ['sarmale', 'mici', 'papanași', 'goulash', 'polenta', 'cabbage', 'beet', 'pomegranate'];
  foods.forEach(food => {
    const count = (allText.match(new RegExp(food, 'g')) || []).length;
    if (count >= 2) themes.push({ theme: food, mentions: count });
  });

  // Check for common concepts
  const concepts = [
    { name: 'authenticity', keywords: ['authentic', 'traditional', 'romanian', 'transylvanian'] },
    { name: 'visual_appeal', keywords: ['instagram', 'visual', 'presentation', 'striking'] },
    { name: 'vampire_theme', keywords: ['vampire', 'blood', 'dracula', 'transylvania'] },
    { name: 'comfort_food', keywords: ['comfort', 'hearty', 'warming', 'traditional'] },
    { name: 'portability', keywords: ['handheld', 'portable', 'on-the-go', 'easy to eat'] }
  ];

  concepts.forEach(concept => {
    const matches = concept.keywords.filter(kw => allText.includes(kw)).length;
    if (matches >= 2) themes.push({ theme: concept.name, strength: matches });
  });

  return themes;
}

// Format high consensus response
const data = $input.item.json;

const output = {
  status: 'success',
  consensus: 'high',
  message: '✅ Strong consensus between AI providers - Safe to proceed',

  recommendation: {
    summary: data.analysis.best_recommendation.recommendation,
    provider: data.analysis.best_recommendation.provider,
    confidence: Math.round(data.analysis.best_recommendation.confidence * 100) + '%',
    consensus_score: Math.round(data.summary.consensus_score * 100) + '%'
  },

  common_themes: data.analysis.common_themes,

  all_responses: data.recommendations.map(r => ({
    provider: r.provider,
    summary: r.recommendation.substring(0, 200) + '...',
    tokens: r.tokens
  })),

  metadata: {
    request_id: data.request_id,
    prompt: data.prompt,
    response_time_ms: data.summary.response_time_ms,
    total_tokens: data.summary.total_tokens,
    estimated_cost: '$' + (data.summary.total_tokens * 0.000006).toFixed(4)
  }
};

return { json: output };

// Format low consensus response - requires human review
const data = $input.item.json;

const output = {
  status: 'review_required',
  consensus: data.analysis.agreement_level,
  message: '⚠️ Low consensus - Human review recommended',

  conflicting_recommendations: data.recommendations.map(r => ({
    provider: r.provider,
    model: r.model,
    recommendation: r.recommendation,
    confidence: Math.round(r.confidence * 100) + '%'
  })),

  analysis: {
    agreement_level: data.analysis.agreement_level,
    consensus_score: Math.round(data.summary.consensus_score * 100) + '%',
    common_themes: data.analysis.common_themes,
    suggestion: 'Review all recommendations and choose based on your business priorities'
  },

  failures: data.failures,

  metadata: {
    request_id: data.request_id,
    prompt: data.prompt,
    response_time_ms: data.summary.response_time_ms,
    total_tokens: data.summary.total_tokens,
    estimated_cost: '$' + (data.summary.total_tokens * 0.000006).toFixed(4)
  }
};

return { json: output };
